use std::sync::{Arc, Mutex};
use std::thread;

let value = Arc::new(Mutex::new(7));
let shared = Arc::clone(&value);
let result = thread::spawn(move || {
    let _guard = shared.lock().unwrap();
    panic!("worker failed");
}).join();
println!("{}", result.is_err());
println!("{}", value.lock().is_err());
